TEST(CrestDtoTest, IovPayloadDtoTest) {
  uint64_t since = 123456789;
  std::string insertionTime = "2026-10-29T12:00:00.000+0000";
  std::string version = "v1.0";
  std::string objectType = "JSON";
  std::string objectName = "test_object";
  std::string compressionType = "gzip";
  int size = 1024;
  std::string payloadHash = "abc123hash";

  // 1. DTO creation (dtoA):
  IovPayloadDto dtoA;
  EXPECT_EQ(0, dtoA.getSince());
  EXPECT_EQ("", dtoA.getInsertionTime());
  EXPECT_EQ("", dtoA.getVersion());
  EXPECT_EQ("", dtoA.getObjectType());
  EXPECT_EQ("", dtoA.getObjectName());
  EXPECT_FALSE(dtoA.getCompressionType().has_value());
  EXPECT_EQ(0, dtoA.getSize());
  EXPECT_EQ("", dtoA.getPayloadHash());

  // 2. Innitialization using the setters:
  dtoA.setSince(since);
  dtoA.setInsertionTime(insertionTime);
  dtoA.setVersion(version);
  dtoA.setObjectType(objectType);
  dtoA.setObjectName(objectName);
  dtoA.setCompressionType(compressionType);
  dtoA.setSize(size);
  dtoA.setPayloadHash(payloadHash);

  // Check for setters/getters:
  EXPECT_EQ(since, dtoA.getSince());
  EXPECT_EQ(insertionTime, dtoA.getInsertionTime());
  EXPECT_EQ(version, dtoA.getVersion());
  EXPECT_EQ(objectType, dtoA.getObjectType());
  EXPECT_EQ(objectName, dtoA.getObjectName());
  EXPECT_TRUE(dtoA.getCompressionType().has_value());
  EXPECT_EQ(compressionType, dtoA.getCompressionType().value());
  EXPECT_EQ(size, dtoA.getSize());
  EXPECT_EQ(payloadHash, dtoA.getPayloadHash());

  // Serialization in JSON:
  nlohmann::json jsA = dtoA.toJson();
  std::cout << "IovPayload A = " << std::endl << jsA.dump(4) << std::endl;

  // 3. DTO creation via JSON (dtoB)
  nlohmann::json jsB = {{"since", since},
                        {"insertionTime", insertionTime},
                        {"version", version},
                        {"objectType", objectType},
                        {"objectName", objectName},
                        {"compressionType", compressionType},
                        {"size", size},
                        {"payloadHash", payloadHash}};

  IovPayloadDto dtoB = IovPayloadDto::fromJson(jsB);
  std::cout << "IovPayload B = " << std::endl << jsB.dump(4) << std::endl;

  // JSON comparison:
  nlohmann::json patch = nlohmann::json::diff(jsA, jsB);
  std::cout << "patch = " << patch << std::endl;
  EXPECT_TRUE(patch.empty()) << "The payloads in test are not identical.";

  // DTO check:
  EXPECT_EQ(dtoA.getSince(), dtoB.getSince());
  EXPECT_EQ(dtoA.getInsertionTime(), dtoB.getInsertionTime());
  EXPECT_EQ(dtoA.getVersion(), dtoB.getVersion());
  EXPECT_EQ(dtoA.getObjectType(), dtoB.getObjectType());
  EXPECT_EQ(dtoA.getObjectName(), dtoB.getObjectName());
  EXPECT_EQ(dtoA.getCompressionType(), dtoB.getCompressionType());
  EXPECT_EQ(dtoA.getSize(), dtoB.getSize());
  EXPECT_EQ(dtoA.getPayloadHash(), dtoB.getPayloadHash());
}

TEST(CrestDtoTest, IovPayloadSetDtoTest) {
  uint64_t since = 123456789;
  std::string insertionTime = "2026-10-29T12:00:00.000+0000";
  std::string version = "v1.0";
  std::string objectType = "JSON";
  std::string objectName = "test_object";
  std::string format = "IovPayloadSetDto";

  // JSON for the IovPayloadDto:
  nlohmann::json jsA = {{"since", since},
                        {"insertionTime", insertionTime},
                        {"version", version},
                        {"objectType", objectType},
                        {"objectName", objectName},
                        {"compressionType", nullptr},
                        {"size", 512},
                        {"payloadHash", "hash123"}};

  IovPayloadDto dtoA = IovPayloadDto::fromJson(jsA);
  std::cout << "IovPayloadDto A = " << std::endl
            << dtoA.toJson().dump(4) << std::endl;

  // 1. IovPayloadSetDto creation:
  std::vector<IovPayloadDto> resA;
  resA.push_back(dtoA);
  IovPayloadSetDto payloadSet(resA);
  std::cout << "IovPayloadSet A = " << std::endl
            << payloadSet.toJson().dump(4) << std::endl;

  // Format check:
  EXPECT_EQ(payloadSet.size(), 1);
  EXPECT_EQ(format, payloadSet.getFormat());

  // JSON comparison:
  std::vector<IovPayloadDto> resB = payloadSet.getResources();
  IovPayloadDto dtoB = resB[0];
  std::cout << "IovPayloadDto B = " << std::endl
            << dtoB.toJson().dump(4) << std::endl;

  std::cout << "111" << std::endl;
  jsA.erase("compressionType");
  nlohmann::json patch = nlohmann::json::diff(jsA, dtoB.toJson());
  std::cout << "patch = " << patch << std::endl;
  EXPECT_TRUE(patch.empty()) << "The IovPayloadSetDtos are not identical.";

  // 2. IovPayloadSetDto creation using JSON:
  nlohmann::json resourcesJs = nlohmann::json::array();
  resourcesJs.push_back(jsA);
  nlohmann::json payloadSetJs = {
      {"format", format}, {"resources", resourcesJs}, {"size", 1}};

  IovPayloadSetDto payloadSetB = IovPayloadSetDto::fromJson(payloadSetJs);

  // IovPayloadSetDto comparison:
  nlohmann::json patchB =
      nlohmann::json::diff(payloadSet.toJson(), payloadSetB.toJson());
  std::cout << "patchB = " << patchB << std::endl;
  EXPECT_TRUE(patchB.empty())
      << "The IovPayloadSetDtos in test are not identical.";

  // 3. Test for the add method:
  IovPayloadDto dtoC = dtoA;
  dtoC.setSince(987654321);
  payloadSet.add(dtoC);
  EXPECT_EQ(payloadSet.size(), 2);
}
